package org.sigf.ui;
import javafx.concurrent.Task;import javafx.scene.control.*;import javafx.scene.layout.*;import org.sigf.config.Database;import org.sigf.services.Operations;import org.sigf.domain.ReportGrid;import java.util.*;import java.util.function.Consumer;
/** Summary and actionable inventory alerts. */
public final class DashboardPane extends VBox {
 private final Operations operations;private final Consumer<String> navigate;private final Label state=new Label("Consultando…");private final HBox cards=new HBox(10);private final TableView<List<String>> low=new TableView<>(),expiry=new TableView<>(),recent=new TableView<>();
 private record Summary(ReportGrid indicators,ReportGrid low,ReportGrid expiry,ReportGrid recent){}
 public DashboardPane(Database db,Consumer<String> navigate){this.operations=new Operations(db);this.navigate=navigate;getStyleClass().add("workspace");setSpacing(12);Label title=new Label("Resumen de la farmacia");title.getStyleClass().add("heading");Button reload=new Button("Actualizar"),products=new Button("Productos"),batches=new Button("Lotes"),sales=new Button("Punto de venta");reload.setOnAction(e->refresh());products.setOnAction(e->navigate.accept("Productos"));batches.setOnAction(e->navigate.accept("Lotes"));sales.setOnAction(e->navigate.accept("Punto de venta"));FlowPane actions=new FlowPane();actions.setHgap(8);actions.setVgap(8);actions.getChildren().addAll(reload,products,batches,sales);for(var t:List.of(low,expiry,recent)){t.setPlaceholder(new Label("Sin alertas o actividad."));t.setPrefHeight(120);t.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_ALL_COLUMNS);}TabPane details=new TabPane();details.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);details.getTabs().addAll(new Tab("Existencias bajas",low),new Tab("Lotes por vencer",expiry),new Tab("Actividad reciente",recent));VBox.setVgrow(details,Priority.ALWAYS);getChildren().addAll(title,actions,cards,details,state);refresh();}
 private void refresh(){state.setText("Consultando…");Task<Summary> task=new Task<>(){protected Summary call()throws Exception{return new Summary(operations.grid("dashboard"),operations.grid("dashboard_low"),operations.grid("dashboard_expiring"),operations.grid("dashboard_recent"));}};task.setOnSucceeded(e->{Summary x=task.getValue();cards.getChildren().clear();if(!x.indicators().rows().isEmpty()){List<String> names=List.of("Productos activos","Unidades vendibles","Lotes por vencer","Productos bajos","Ventas de hoy");for(int i=0;i<names.size();i++){Label number=new Label(x.indicators().rows().get(0).get(i));number.getStyleClass().add("metric-value");Label label=new Label(names.get(i));label.getStyleClass().add("muted");VBox card=new VBox(5,label,number);card.getStyleClass().add("metric-card");cards.getChildren().add(card);HBox.setHgrow(card,Priority.ALWAYS);}}show(low,x.low());show(expiry,x.expiry());show(recent,x.recent());state.setText("Actualizado");});task.setOnFailed(e->state.setText("No se pudo consultar: "+Objects.toString(task.getException().getMessage(),"error")));Thread t=new Thread(task,"sigf-dashboard");t.setDaemon(true);t.start();}
 private static void show(TableView<List<String>> t,ReportGrid g){t.getColumns().clear();for(int i=0;i<g.columns().size();i++){final int n=i;TableColumn<List<String>,String> column=new TableColumn<>(g.columns().get(i).replace('_',' '));column.setCellValueFactory(v->new javafx.beans.property.ReadOnlyStringWrapper(v.getValue().get(n)));column.setMinWidth(80);column.setPrefWidth(150);t.getColumns().add(column);}t.getItems().setAll(g.rows());}
}
